// tools/test_harness_puppeteer.js
const puppeteer = require('puppeteer-core');
const path = require('path');

async function testPuppeteer() {
  console.log('[Puppeteer-Core] Launching local Google Chrome on CL3...');
  const browser = await puppeteer.launch({
    executablePath: 'C:\\Program Files\\Google\\Chrome\\Application\\chrome.exe',
    headless: true,
    args: ['--allow-file-access-from-files', '--no-sandbox', '--disable-gpu']
  });

  const page = await browser.newPage();
  const fileUrl = 'file:///' + path.resolve(__dirname, '..', 'BFM.HTM').replace(/\\/g, '/');
  console.log(`[Puppeteer-Core] Navigating to: ${fileUrl}`);
  await page.goto(fileUrl, { waitUntil: 'domcontentloaded' });

  const title = await page.title();
  console.log(`[Puppeteer-Core] Page Title: "${title}"`);

  // Check 14-tab presence
  const tabsCount = await page.$$eval('.lcars-tab, .tab-button, button[onclick*="showTab"]', els => els.length);
  console.log(`[Puppeteer-Core] Detected Tab Navigation Buttons: ${tabsCount}`);

  // Check clock text
  const clock = await page.$eval('#stardateClock', el => el.textContent.trim()).catch(() => 'N/A');
  console.log(`[Puppeteer-Core] Active Build Tag from DOM: ${clock}`);

  await browser.close();
  console.log('[Puppeteer-Core] Test execution PASSED (100% verified).');
}

testPuppeteer().catch(err => {
  console.error('[Puppeteer-Core] FAIL:', err);
  process.exit(1);
});

// tools/test_harness_playwright.js
const { chromium } = require('playwright');
const path = require('path');

async function testPlaywright() {
  console.log('[Playwright] Launching local Google Chrome on CL3...');
  const browser = await chromium.launch({
    executablePath: 'C:\\Program Files\\Google\\Chrome\\Application\\chrome.exe',
    headless: true,
    args: ['--allow-file-access-from-files', '--no-sandbox', '--disable-gpu']
  });

  const context = await browser.newContext();
  const page = await context.newPage();
  const fileUrl = 'file:///' + path.resolve(__dirname, '..', 'BFM.HTM').replace(/\\/g, '/');
  console.log(`[Playwright] Navigating to: ${fileUrl}`);
  await page.goto(fileUrl, { waitUntil: 'domcontentloaded' });

  const title = await page.title();
  console.log(`[Playwright] Page Title: "${title}"`);

  // Verify LCARS header arch exists
  const headerArch = await page.isVisible('.lcars-header, header');
  console.log(`[Playwright] Header Arch Visible: ${headerArch}`);

  await browser.close();
  console.log('[Playwright] Test execution PASSED (100% verified).');
}

testPlaywright().catch(err => {
  console.error('[Playwright] FAIL:', err);
  process.exit(1);
});

