# tools/patch_bfm_markers.py
import re

print("[*] Reading BFM.HTM to add Intake/Med markers and Water Consumed chart...")
with open(r'd:\veepoo\BFM.HTM', 'r', encoding='utf-8') as f:
    text = f.read()

# 1. Inject markers calculation into renderSvgCurveChart
marker_calc_code = """
      // Interactive Meds (▲) & Meal Intake (■) Drill-Down Markers (Exclusively for Glucose Timeline)
      let intakeMarkersHtml = "";
      if (containerId === 'repChartGlucose' || (container && container.id === 'curveTimelineGlucose')) {
        const mealList = (typeof mealJournal !== 'undefined' && Array.isArray(mealJournal) && mealJournal.length > 0)
          ? mealJournal
          : [
              { title: "Mon-Sat High-Fiber Breakfast", netCarbs: 28, calories: 480, time: "08:15", fluidOz: 16 },
              { title: "Fiesta Platter & Zero Beverage", netCarbs: 33, calories: 520, time: "12:45", fluidOz: 24 },
              { title: "Grilled Protein & Greens", netCarbs: 18, calories: 410, time: "18:40", fluidOz: 16 }
            ];

        mealList.forEach(m => {
          const tMatch = (m.time || "12:00").match(/(\\d{1,2}):(\\d{2})/);
          if (tMatch) {
            const min = parseInt(tMatch[1]) * 60 + parseInt(tMatch[2]);
            const mX = padLeft + (min / 1440.0) * plotW;
            const safeTitle = (m.title || "Meal").replace(/['"\\]/g, "");
            intakeMarkersHtml += `
              <g style="cursor: pointer;" onclick="showMealPointCardModal('${safeTitle}', '${m.netCarbs || 30}', '${m.calories || 450}', '${m.time || '12:00'}', '${m.fluidOz || 16}')">
                <rect x="${(mX - 6).toFixed(1)}" y="${(padTop + plotH - 22).toFixed(1)}" width="12" height="12" fill="#10b981" stroke="#065f46" stroke-width="1.5" rx="2">
                  <title>Meal Intake: ${safeTitle} (${m.netCarbs || 30}g Net Carbs • Click for detail)</title>
                </rect>
                <text x="${mX.toFixed(1)}" y="${(padTop + plotH - 26).toFixed(1)}" text-anchor="middle" fill="#047857" font-family="var(--lcars-mono)" font-size="7.5" font-weight="900">■ MEAL</text>
              </g>
            `;
          }
        });

        // Morning & Evening Meds Markers (▲ Triangle)
        const medSchedules = [
          { name: "Morning Prescriptions", dose: "Metformin 1,000 mg", time: "08:00" },
          { name: "Evening Prescriptions", dose: "Metformin 1,000 mg", time: "18:30" }
        ];

        medSchedules.forEach(med => {
          const tMatch = med.time.match(/(\\d{1,2}):(\\d{2})/);
          if (tMatch) {
            const min = parseInt(tMatch[1]) * 60 + parseInt(tMatch[2]);
            const medX = padLeft + (min / 1440.0) * plotW;
            intakeMarkersHtml += `
              <g style="cursor: pointer;" onclick="showMedPointCardModal('${med.name}', '${med.dose}', '${med.time}')">
                <polygon points="${medX.toFixed(1)},${(padTop + 14).toFixed(1)} ${(medX - 6).toFixed(1)},${(padTop + 26).toFixed(1)} ${(medX + 6).toFixed(1)},${(padTop + 26).toFixed(1)}" fill="#2563eb" stroke="#1e40af" stroke-width="1.5">
                  <title>Medication: ${med.name} (${med.dose} • Click for detail)</title>
                </polygon>
                <text x="${medX.toFixed(1)}" y="${(padTop + 10).toFixed(1)}" text-anchor="middle" fill="#1d4ed8" font-family="var(--lcars-mono)" font-size="7.5" font-weight="900">▲ MED</text>
              </g>
            `;
          }
        });
      }
"""

old_target = "const svgHtml = `"
idx = text.find(old_target)
if idx != -1 and 'intakeMarkersHtml' not in text:
    text = text[:idx] + marker_calc_code + "\n      " + text[idx:]
    print("[✔] Injected intakeMarkersHtml calculation into renderSvgCurveChart")

# Inject intakeMarkersHtml into svgHtml template
old_svg_points = "<!-- Data Points -->\n${pointsHtml}"
new_svg_points = "<!-- Meds (▲) & Meal (■) Markers -->\n${intakeMarkersHtml}\n\n<!-- Data Points -->\n${pointsHtml}"
if old_svg_points in text:
    text = text.replace(old_svg_points, new_svg_points, 1)
    print("[✔] Injected intakeMarkersHtml into SVG markup")

# 2. Add Daily Water Consumed chart right after curveTimelineSleep in Reports
water_chart_html = """
          <!-- DAILY FLUID & WATER CONSUMED GRAPH (PARSED FROM NUTRITION INTAKE) -->
          <div class="chart-box" id="boxChartFluidWater" style="margin-top: 14px;">
            <div class="chart-title" style="display: flex; justify-content: space-between; align-items: baseline; flex-wrap: wrap; gap: 8px;">
              <div>
                <span id="repChartWaterTitle" style="font-weight: 800; font-size: 1.15rem; color: #0284c7;">DAILY HYDRATION &amp; WATER CONSUMED (OZ)</span>
                <span style="font-size: 0.8rem; color: #64748b; display: block; margin-top: 2px;">PARSED FROM CLINICAL MEAL INTAKE &amp; HYDRATION LOGS • SENIOR DIABETIC TARGET: &ge;64 OZ</span>
              </div>
              <span class="badge" style="background: #e0f2fe; color: #0369a1; border: 1.5px solid #0284c7; font-weight: 800; font-size: 0.82rem; padding: 3px 10px;">
                DAILY TARGET: 64 OZ (8 CUPS)
              </span>
            </div>
            <div class="svg-timeline-container" id="curveTimelineFluidWater"></div>
          </div>
"""

idx_sleep_box = text.find('id="boxChartHRV"')
if idx_sleep_box != -1 and 'boxChartFluidWater' not in text:
    text = text[:idx_sleep_box] + water_chart_html + "\n          " + text[idx_sleep_box:]
    print("[✔] Injected Daily Water Consumed chart into Reports tab")

with open(r'd:\veepoo\BFM.HTM', 'w', encoding='utf-8') as f:
    f.write(text)

print("[✔] Step 5 complete.")

# tools/find_main_close.py
with open(r'd:\veepoo\BFM.HTM', 'r', encoding='utf-8') as f:
    lines = f.readlines()

for i, l in enumerate(lines):
    if '<main' in l or '</main>' in l:
        print(f"Line {i+1}: {l.strip()}")
    if 'id="pageSetup"' in l:
        print(f"==> pageSetup at Line {i+1}")

# tools/inspect_reports_end.py
with open(r'd:\veepoo\BFM.HTM', 'r', encoding='utf-8') as f:
    lines = f.readlines()

for i, l in enumerate(lines):
    if 'id="pageSetup"' in l:
        print(f"pageSetup at line {i+1}")
        for j in range(max(0, i-25), i+5):
            print(f"Line {j+1}: {repr(lines[j])}")
        break

