        if (!flOz && entry.title && entry.title.toLowerCase().includes('tea')) flOz = 16;
        if (!flOz && entry.title && entry.title.toLowerCase().includes('beverage')) flOz = 24;
        if (!flOz && entry.title && entry.title.toLowerCase().includes('water')) flOz = 16;

        let hr = 12;
        if (entry.time) {
          const m = entry.time.match(/(\\d{1,2}):/);
          if (m) hr = Math.min(23, Math.max(0, parseInt(m[1])));
        }
        hourlyFluid[hr] += flOz;
      });

      for (let h = 0; h < 24; h++) {
        cumulative += hourlyFluid[h];
        cumulativeByHour.push({ hour: h, totalOz: cumulative });
      }

      const curH = new Date().getHours();
      const currentTotalOz = cumulativeByHour[curH].totalOz;
      const targetOz = 64;
