      const points = [];
      for (let h = 0; h <= 24; h++) {
        const x = padLeft + (h / 24.0) * plotW;
        const val = (h <= curH) ? cumulativeByHour[Math.min(23, h)].totalOz : (h === curH + 1 ? currentTotalOz : 0);
        const isFuture = h > curH;
        const y = padTop + plotH - ((isFuture ? 0 : val) / maxAxisOz) * plotH;
        points.push({ x, y, val: isFuture ? 0 : val, isFuture, h });
      }

      const pastPoints = points.filter(p => !p.isFuture);
      let stepPath = "";
