            <span style="font-size: 0.82rem; color: #64748b; font-weight: 700;">(${Math.round(currentTotalOz * 29.5735)} mL) • ${targetPct}% OF SENIOR TARGET</span>
          </div>
          <div style="display: flex; gap: 6px;">
            <span class="badge" style="background: ${targetPct >= 80 ? '#dcfce7' : '#fef08a'}; color: ${targetPct >= 80 ? '#15803d' : '#854d0e'}; border: 1.5px solid ${targetPct >= 80 ? '#86efac' : '#ca8a04'}; font-weight: 800; font-size: 0.76rem; padding: 3px 8px;">
              ${targetPct >= 100 ? 'OPTIMAL HYDRATION REACHED' : (targetPct >= 60 ? 'ON TRACK (SENIOR TARGET: 64 OZ)' : 'HYDRATION ATTENTION NEEDED')}
