# tools/apply_audit_fixes_v16.py
import re
import sys

with open('BFM.HTM', 'r', encoding='utf-8') as f:
    content = f.read()

orig_len = len(content)
print(f"Original BFM.HTM length: {orig_len}")

# -----------------------------------------------------------------------------
# 1. Bump Build Tag to beta.00.01.0016
# -----------------------------------------------------------------------------
content = content.replace("BUILD beta.00.01.0015", "BUILD beta.00.01.0016")

# -----------------------------------------------------------------------------
# 2. Meal Pantry Zero Data & Init
# -----------------------------------------------------------------------------
# A. Empty out DEFAULT_POPULAR_MEALS
old_default_pantry_def = re.search(r'const DEFAULT_POPULAR_MEALS = \{.*?\n    \};', content, re.DOTALL)
if old_default_pantry_def:
    print("Found DEFAULT_POPULAR_MEALS definition, setting to empty object...")
    content = content[:old_default_pantry_def.start()] + "const DEFAULT_POPULAR_MEALS = {};" + content[old_default_pantry_def.end():]
else:
    print("Notice: DEFAULT_POPULAR_MEALS not found via regex, checking simple replace...")
    content = re.sub(r'const DEFAULT_POPULAR_MEALS = \{[\s\S]*?\n    \};', 'const DEFAULT_POPULAR_MEALS = {};', content)

# B. Update initPopularMeals to purge synthetic legacy meals and initialize empty
old_init_pantry = """    function initPopularMeals() {
      try {
        const stored = localStorage.getItem('lcars_popular_meals');
        if (stored) {
          POPULAR_MEALS = JSON.parse(stored);
        } else {
          POPULAR_MEALS = JSON.parse(JSON.stringify(DEFAULT_POPULAR_MEALS));
          savePopularMealsToStorage();
        }
      } catch (e) {
        POPULAR_MEALS = JSON.parse(JSON.stringify(DEFAULT_POPULAR_MEALS));
      }

      syncPopularMealsWithServer();
      renderPopularMealsPullDown();
      renderPopularMealsManager();
      renderLongitudinalView();
    }"""

new_init_pantry = """    function initPopularMeals() {
      try {
        const stored = localStorage.getItem('lcars_popular_meals');
        if (stored) {
