const puppeteer = require('puppeteer-core');

(async () => {
  const browser = await puppeteer.launch({
    executablePath: 'C:\\Program Files\\Google\\Chrome\\Application\\chrome.exe',
    headless: true
  });
  const page = await browser.newPage();
  page.on('console', msg => console.log('BROWSER CONSOLE:', msg.type(), msg.text()));
  page.on('pageerror', err => console.error('BROWSER PAGE ERROR:', err));
  await page.goto('file:///D:/veepoo/BFM.HTM', { waitUntil: 'load' });
  await new Promise(r => setTimeout(r, 1000));

  // Step 1: Click the token
  console.log('--- Step 1: setting token ---');
  await page.evaluate(() => {
    setMealQueryToken("find me a sugar free dessert like 'blueberry cake'");
  });
  await new Promise(r => setTimeout(r, 500));
  const title1 = await page.evaluate(() => document.getElementById('lblGeminiMealTitle')?.textContent);
  console.log('Title 1:', title1);

  // Step 2: User types chicken dinner
  console.log('--- Step 2: entering chicken dinner ---');
  await page.evaluate(() => {
    const inp = document.getElementById('txtMealBuilderInput');
    inp.value = '6oz breaded chicken, 3oz lettuce and baby tomato salad, 3 oz cottage cheese, 12 oz water';
  });

  // Step 3: User clicks ESTIMATE WITH GEMINI
  console.log('--- Step 3: clicking ESTIMATE WITH GEMINI ---');
  await page.evaluate(async () => {
    await analyzeMealWithGemini();
  });
  await new Promise(r => setTimeout(r, 1500));
  const res = await page.evaluate(() => {
    return {
      title: document.getElementById('lblGeminiMealTitle')?.textContent,
      calories: document.getElementById('chipCalories')?.textContent,
      netCarbs: document.getElementById('chipNetCarbs')?.textContent,
      safeTarget: document.getElementById('lblSafeOptionTarget')?.textContent,
      safeCardDisplay: document.getElementById('cardSafeOptionsDiscovery')?.style.display
    };
  });
  console.log('Result after estimate:', JSON.stringify(res, null, 2));

  await browser.close();
})();

