    bfm = f.read()

with open(server_path, "r", encoding="utf-8") as f:
    server = f.read()

# -----------------------------------------------------------------------------
# 1. Purge synthetic test meals from telemetry.db popular_meals & meal_entries
# -----------------------------------------------------------------------------
db_path = "D:/veepoo/w11_htm_app/telemetry.db"
if os.path.exists(db_path):
    conn = sqlite3.connect(db_path)
    cur = conn.cursor()
    # Delete synthetic/fake demo meals that user did not enter
    cur.execute("DELETE FROM popular_meals WHERE title LIKE '%Banquet%' OR title LIKE '%Soup%' OR title LIKE '%Dick%' OR title LIKE '%Clove%' OR title LIKE '%Granola%' OR title LIKE '%MEAL-01%'")
    cur.execute("DELETE FROM meal_entries WHERE meal_name LIKE '%Weekly vegetable%' OR meal_name LIKE '%Banquet Beef%' OR meal_name LIKE '%Mon-Sat High-Fiber%'")
    conn.commit()
    conn.close()
    print("[+] Purged synthetic demo meals from telemetry.db.")

# -----------------------------------------------------------------------------
# 2. Multi-Watch H8 / 5010 Persistence in renderWatchTabConnectedDetails()
# -----------------------------------------------------------------------------
old_render_watch = '''    function renderWatchTabConnectedDetails() {
      const isH8 = (window._connectedWatchId === 'H8_VX001') || 
                   (typeof bluetoothDevice !== 'undefined' && bluetoothDevice && bluetoothDevice.name && (bluetoothDevice.name.includes('H8') || bluetoothDevice.name.includes('VX001') || bluetoothDevice.name.includes('vx01')));'''

new_render_watch = '''    function renderWatchTabConnectedDetails() {
      const persistedId = (typeof localStorage !== 'undefined') ? localStorage.getItem('bfm_connected_watch_id') : null;
      const isH8 = (window._connectedWatchId === 'H8_VX001') || 
                   (persistedId === 'H8_VX001') ||
                   (typeof bluetoothDevice !== 'undefined' && bluetoothDevice && bluetoothDevice.name && (bluetoothDevice.name.includes('H8') || bluetoothDevice.name.includes('VX001') || bluetoothDevice.name.includes('vx01')));'''

if old_render_watch in bfm:
    bfm = bfm.replace(old_render_watch, new_render_watch, 1)
    print("[+] Updated renderWatchTabConnectedDetails with persisted watch id.")
else:
    print("[!] Warning: old_render_watch target not found, checking if already patched.")

# Also ensure on DOMContentLoaded that renderWatchTabConnectedDetails() is initialized:
if "renderWatchTabConnectedDetails();" not in bfm[bfm.find("DOMContentLoaded"):bfm.find("DOMContentLoaded") + 1500]:
    old_dcl = "window.addEventListener('DOMContentLoaded', () => {"
    new_dcl = "window.addEventListener('DOMContentLoaded', () => {\n      try { renderWatchTabConnectedDetails(); } catch (e) {}"
    bfm = bfm.replace(old_dcl, new_dcl, 1)
    print("[+] Added renderWatchTabConnectedDetails to DOMContentLoaded.")

# -----------------------------------------------------------------------------
# 3. Clinical Goal Recalc Progress Animation (0% to 100% active sweep)
# -----------------------------------------------------------------------------
old_recalc_goal = '''      if (lblRecalcNum) {
        lblRecalcNum.textContent = "0% (RECALCULATING...)";
        lblRecalcNum.style.background = "#fef08a";
        lblRecalcNum.style.color = "#854d0e";
        setTimeout(() => { if (lblRecalcNum) lblRecalcNum.textContent = "25% (ANALYZING SENSORS...)"; }, 80);
        setTimeout(() => { if (lblRecalcNum) lblRecalcNum.textContent = "50% (RECONCILING GOALS...)"; }, 160);
        setTimeout(() => { if (lblRecalcNum) lblRecalcNum.textContent = "75% (WEIGHTING DOMAINS...)"; }, 240);
        setTimeout(() => {
          if (lblRecalcNum) {
            lblRecalcNum.textContent = `${compositeScore.toFixed(1)}% MET (CURRENT)`;
            lblRecalcNum.style.background = "#dcfce7";
            lblRecalcNum.style.color = "#15803d";
          }
          if (lblCompositePercent) {
            lblCompositePercent.textContent = `${compositeScore.toFixed(1)}%`;
          }
          if (circleProgress) {
            const circumference = 2 * Math.PI * 42; // ~263.89
            const offset = circumference - (compositeScore / 100) * circumference;
            circleProgress.style.strokeDashoffset = offset.toFixed(1);
          }
        }, 320);
      }'''

new_recalc_goal = '''      if (lblRecalcNum) {
        let currentP = 0;
        const circumference = 2 * Math.PI * 42; // ~263.89
        if (circleProgress) circleProgress.style.transition = "stroke-dashoffset 0.04s ease-out";
        const animInterval = setInterval(() => {
          currentP += 10;
          if (currentP <= 100) {
            if (lblRecalcNum) {
              lblRecalcNum.textContent = `${currentP}% (RECALCULATING...)`;
              lblRecalcNum.style.background = "#fef08a";
              lblRecalcNum.style.color = "#854d0e";
            }
            if (lblCompositePercent) {
              lblCompositePercent.textContent = `${currentP}%`;
            }
            if (circleProgress) {
              const sweepOffset = circumference - (currentP / 100) * circumference;
              circleProgress.style.strokeDashoffset = sweepOffset.toFixed(1);
            }
          } else {
            clearInterval(animInterval);
            if (lblRecalcNum) {
              lblRecalcNum.textContent = `${compositeScore.toFixed(1)}% MET (CURRENT)`;
              lblRecalcNum.style.background = "#dcfce7";
              lblRecalcNum.style.color = "#15803d";
            }
            if (lblCompositePercent) {
              lblCompositePercent.textContent = `${compositeScore.toFixed(1)}%`;
            }
            if (circleProgress) {
              const finalOffset = circumference - (compositeScore / 100) * circumference;
              circleProgress.style.strokeDashoffset = finalOffset.toFixed(1);
            }
            if (typeof soundSuccess === 'function') soundSuccess();
          }
        }, 35);
      }'''

