    // 12/24-HOUR CHRONOMETER TIME FORMATTING HELPER
    // =========================================================================
    function formatTimeDisplay(timeStr) {
      if (!timeStr) return "";
      const is12 = (typeof getInt === 'function' ? getInt('cfgTimeFormat', 12) : 12) === 12;
      if (!is12) return timeStr;
      const m = timeStr.match(/(\\d{1,2}):(\\d{2})/);
      if (!m) return timeStr;
      let h = parseInt(m[1], 10);
      const min = m[2];
      const ampm = h >= 12 ? 'PM' : 'AM';
      let h12 = h % 12;
      if (h12 === 0) h12 = 12;
      return `${h12}:${min} ${ampm}`;
    }
'''
    insert_pos = bfm.find("function renderWatchTabConnectedDetails()")
