bfm = re.sub(
    r'<text x="\$\{xCoords\[lastIdx\]\}" y="\$\{H - 18\}" text-anchor="middle" fill="var\(--lcars-gray\)" font-size="10\.5" font-weight="bold">\$\{data\[lastIdx\]\.time\}</text>',
