    bfm
)
print("[+] Applied formatTimeDisplay to tall chart bottom time axis.")

# -----------------------------------------------------------------------------
# 5. Connect Hydration Journal Data to Daily Hydration Chart
# -----------------------------------------------------------------------------
old_hydr_source = '''      const journalEntries = (typeof dietJournal !== 'undefined' && Array.isArray(dietJournal) && dietJournal.length > 0)
        ? dietJournal
        : ((typeof mealJournal !== 'undefined' && Array.isArray(mealJournal)) ? mealJournal : []);'''

new_hydr_source = '''      // Unified multi-source hydration intake aggregator (DB + Ingested Log + Memory)
      const allSources = [];
      if (typeof patientDietaryLog !== 'undefined' && Array.isArray(patientDietaryLog)) allSources.push(...patientDietaryLog);
      if (typeof window._cachedRecentMeals !== 'undefined' && Array.isArray(window._cachedRecentMeals)) allSources.push(...window._cachedRecentMeals);
      if (typeof dietJournal !== 'undefined' && Array.isArray(dietJournal)) allSources.push(...dietJournal);
      if (typeof mealJournal !== 'undefined' && Array.isArray(mealJournal)) allSources.push(...mealJournal);

      const seenHydrKeys = new Set();
      const journalEntries = [];
      allSources.forEach((entry, idx) => {
        const key = (entry.timestamp || entry.time || '') + '_' + (entry.meal_name || entry.name || entry.title || idx);
        if (!seenHydrKeys.has(key)) {
          seenHydrKeys.add(key);
          journalEntries.push(entry);
        }
      });'''

if old_hydr_source in bfm:
    bfm = bfm.replace(old_hydr_source, new_hydr_source, 1)
    print("[+] Connected unified multi-source hydration journal to Daily Hydration Chart.")
else:
    print("[!] Warning: old_hydr_source target not found.")

# Also enhance fluid extraction logic in renderDailyHydrationChart:
