const puppeteer = require('puppeteer-core');

async function testExactUserScreen() {
  const browser = await puppeteer.launch({
    headless: "new",
    executablePath: "C:\\Program Files\\Google\\Chrome\\Application\\chrome.exe",
    args: ['--no-sandbox', '--disable-setuid-sandbox', '--allow-file-access-from-files']
  });

  const page = await browser.newPage();
  const consoleLogs = [];
  page.on('console', msg => consoleLogs.push(msg.text()));

  console.log("Navigating to file:///D:/veepoo/BFM.HTM...");
  await page.goto('file:///D:/veepoo/BFM.HTM', { waitUntil: 'domcontentloaded', timeout: 30000 });
  await page.waitForTimeout(2000);

  // Check what is in listboxPopularMeals
  const listboxOptions = await page.evaluate(() => {
    const lb = document.getElementById('listboxPopularMeals');
    if (!lb) return [];
    return Array.from(lb.options).map(o => ({ value: o.value, text: o.text }));
  });
  console.log("Initial listboxPopularMeals options:", listboxOptions);

  // Check input and button
  const inputExists = await page.evaluate(() => !!document.getElementById('txtMealBuilderInput'));
  console.log("Input txtMealBuilderInput exists:", inputExists);

  // Type user string:
  const testInput = "6oz breaded chicken, 3oz lettuce and baby tomato salad, 3 oz cottage cheese, 12 oz water";
  await page.evaluate((val) => {
    const input = document.getElementById('txtMealBuilderInput');
    input.value = val;
    input.dispatchEvent(new Event('input', { bubbles: true }));
  }, testInput);

  console.log("Clicking ESTIMATE WITH GEMINI...");
  await page.evaluate(() => {
    const btn = document.querySelector('button[onclick="analyzeMealWithGemini()"]');
    if (btn) btn.click();
    else if (typeof analyzeMealWithGemini === 'function') analyzeMealWithGemini();
  });

  await page.waitForTimeout(3000);

  // Read estimation card title and values
  const resultData = await page.evaluate(() => {
    const titleEl = document.getElementById('lblSafeOptionTarget');
    const calEl = document.getElementById('lblPreChoiceCals');
    const netEl = document.getElementById('lblPreChoiceNetCarbs');
    const card = document.getElementById('cardPreChoiceNutrition');
    return {
      cardDisplay: card ? card.style.display : null,
      title: titleEl ? titleEl.textContent.trim() : null,
      cals: calEl ? calEl.textContent.trim() : null,
      netCarbs: netEl ? netEl.textContent.trim() : null
    };
  });
  console.log("Result after ESTIMATE WITH GEMINI:", resultData);

  await browser.close();
}

testExactUserScreen().catch(err => {
  console.error("Test failed:", err);
  process.exit(1);
});

