function runGoalComplianceAudit(animate = true) {
  if (window._goalAuditAnimInterval) {
    clearInterval(window._goalAuditAnimInterval);
    window._goalAuditAnimInterval = null;
  }
  const goals = getActiveClinicalGoals();

  // 1. Daily Steps Compliance against active target (default 2000 steps)
  const targetSteps = parseInt(goals.stepTarget) || 2000;
  const actualSteps = (typeof lastSteps === 'number' && lastSteps > 0) ? lastSteps : 0;
  const stepRatio = Math.min(100, Math.round((actualSteps / targetSteps) * 100));

  // 2. TIR Compliance: based on live / recent glucose
  const g = (typeof lastGlucoseMg === 'number' && lastGlucoseMg > 0) ? lastGlucoseMg : 0;
  let tirRatio = 0;
  if (g > 0) {
    tirRatio = (g >= 70 && g <= 180) ? 100 : Math.max(20, Math.round(100 - Math.abs(g - 120) * 0.8));
  }

  // 3. Dietary Compliance: percentage of logged meals <= 45g net carbs
  const meals = (typeof patientDietaryLog !== 'undefined' && Array.isArray(patientDietaryLog)) ? patientDietaryLog : [];
  let dietRatio = 100;
  if (meals.length > 0) {
    const compliantMeals = meals.filter(m => (m.net_carbs || m.netCarbs || 0) <= goals.maxCarbsMeal).length;
    dietRatio = Math.round((compliantMeals / meals.length) * 100);
  }

  // 4. Nocturnal Glycemic Stability Ratio
  const noctRatio = (typeof lastHypnoScore === 'number' && lastHypnoScore > 0) ? lastHypnoScore : 88;

  // 5. Blood Pressure Compliance
  const bpSys = (typeof lastSysBp === 'number' && lastSysBp > 0) ? lastSysBp : 120;
  const bpDia = (typeof lastDiaBp === 'number' && lastDiaBp > 0) ? lastDiaBp : 80;
  const bpRatio = (bpSys <= goals.maxBpSys && bpDia <= goals.maxBpDia) ? 100 : 75;

  // 6. Medication Adherence
  const medRatio = (typeof medAdherenceScore === 'number') ? medAdherenceScore : 100;

  // 7. Hydration Compliance: against 64 oz fluid target
  const targetHydration = 64;
  const actualHydration = (typeof currentDailyHydrationOz === 'number') ? currentDailyHydrationOz : 48;
  const hydrRatio = Math.min(100, Math.round((actualHydration / targetHydration) * 100));

  // Weighted Composite Score
  const compositeScore = Math.round(
    (tirRatio * 0.28) +
    (dietRatio * 0.22) +
    (stepRatio * 0.15) +
    (noctRatio * 0.12) +
    (bpRatio * 0.10) +
    (medRatio * 0.08) +
    (hydrRatio * 0.05)
  );

  const lblRecalcNum = document.getElementById('lblAuditRecalcNumber');
  const lblCompositePercent = document.getElementById('lblAuditCompositePercent');
  const circleProgress = document.getElementById('circleGoalAuditProgress');
  const circumference = 2 * Math.PI * 42; // ~263.89

  if (!animate) {
    if (lblRecalcNum) {
      lblRecalcNum.textContent = `${compositeScore.toFixed(1)}% MET (CURRENT)`;
      lblRecalcNum.style.background = "#dcfce7";
      lblRecalcNum.style.color = "#15803d";
    }
    if (lblCompositePercent) {
      lblCompositePercent.textContent = `${compositeScore.toFixed(1)}%`;
    }
    if (circleProgress) {
      const finalOffset = circumference - (compositeScore / 100) * circumference;
      circleProgress.style.strokeDashoffset = finalOffset.toFixed(1);
    }
    return;
  }

  if (lblRecalcNum) {
    let currentP = 0;
    if (circleProgress) circleProgress.style.transition = "stroke-dashoffset 0.02s ease-out";
    window._goalAuditAnimInterval = setInterval(() => {
      currentP += 20;
      if (currentP <= 100) {
        if (lblRecalcNum) {
          lblRecalcNum.textContent = `${currentP}% (RECALCULATING...)`;
          lblRecalcNum.style.background = "#fef08a";
          lblRecalcNum.style.color = "#854d0e";
        }
        if (lblCompositePercent) {
          lblCompositePercent.textContent = `${currentP}%`;
        }
        if (circleProgress) {
          const sweepOffset = circumference - (currentP / 100) * circumference;
          circleProgress.style.strokeDashoffset = sweepOffset.toFixed(1);
        }
      } else {
        clearInterval(window._goalAuditAnimInterval);
        window._goalAuditAnimInterval = null;
        if (lblRecalcNum) {
          lblRecalcNum.textContent = `${compositeScore.toFixed(1)}% MET (CURRENT)`;
          lblRecalcNum.style.background = "#dcfce7";
          lblRecalcNum.style.color = "#15803d";
        }
        if (lblCompositePercent) {
          lblCompositePercent.textContent = `${compositeScore.toFixed(1)}%`;
        }
        if (circleProgress) {
          const finalOffset = circumference - (compositeScore / 100) * circumference;
          circleProgress.style.strokeDashoffset = finalOffset.toFixed(1);
        }
        if (typeof soundSuccess === 'function') soundSuccess();
      }
    }, 25);
  }
}

