const puppeteer = require('puppeteer-core');

(async () => {
  const browser = await puppeteer.launch({
    headless: 'new',
    executablePath: 'C:\\Program Files\\Google\\Chrome\\Application\\chrome.exe',
    args: ['--no-sandbox', '--allow-file-access-from-files']
  });
  const page = await browser.newPage();
  await page.goto('file:///D:/veepoo/BFM.HTM', { waitUntil: 'domcontentloaded' });
  await new Promise(r => setTimeout(r, 1000));

  const tabList = [
    { tabId: 'fullscan', pageId: 'pageFullScan' },
    { tabId: 'diettrades', pageId: 'pageDietTrades' },
    { tabId: 'metabolic', pageId: 'pageMetabolic' },
    { tabId: 'reports', pageId: 'pageReports' },
    { tabId: 'learning', pageId: 'pageLearning' },
    { tabId: 'operations', pageId: 'pageOperations' },
    { tabId: 'help', pageId: 'pageHelp' },
    { tabId: 'goals', pageId: 'pageGoals' },
    { tabId: 'medication', pageId: 'pageMedication' },
    { tabId: 'setup', pageId: 'pageSetup' },
    { tabId: 'watchfaces', pageId: 'pageWatchFaces' },
    { tabId: 'log', pageId: 'pageLog' },
    { tabId: 'export', pageId: 'pageExport' },
    { tabId: 'troubleshooting', pageId: 'pageTroubleshooting' }
  ];

  console.log("=== Testing All 14 Tab Visibilities ===");
  let allPass = true;
  for (const t of tabList) {
    await page.evaluate((id) => switchTab(id), t.tabId);
    await new Promise(r => setTimeout(r, 150));
    const disp = await page.evaluate((id) => {
      const el = document.getElementById(id);
      return el ? window.getComputedStyle(el).display : 'NOT_FOUND';
    }, t.pageId);

    const ok = disp === 'flex' || disp === 'block';
    console.log(`Tab [${t.tabId}] -> Page [${t.pageId}]: display=${disp} ${ok ? '✅ PASS' : '❌ FAIL'}`);
    if (!ok) allPass = false;
  }

  // Switch back to Tab 01 Full Scan
  await page.evaluate(() => switchTab('fullscan'));
  await new Promise(r => setTimeout(r, 150));
  const fullScanDisp = await page.evaluate(() => window.getComputedStyle(document.getElementById('pageFullScan')).display);
  console.log(`Initial Tab 01 fullscan display: ${fullScanDisp} ${fullScanDisp === 'flex' ? '✅ PASS' : '❌ FAIL'}`);

  await browser.close();
  if (!allPass) process.exit(1);
  console.log("=== ALL 14 TABS VERIFIED VISIBLE (100% PASS) ===");
})();

