const puppeteer = require('puppeteer-core');
(async () => {
    const browser = await puppeteer.launch({
        headless: 'new',
        executablePath: 'C:\\Program Files\\Google\\Chrome\\Application\\chrome.exe',
        args: ['--no-sandbox', '--allow-file-access-from-files']
    });
    const page = await browser.newPage();
    await page.setViewport({ width: 1400, height: 900 });

    await page.goto('file:///D:/veepoo/BFM.HTM', { waitUntil: 'domcontentloaded' });
    await new Promise(r => setTimeout(r, 1000));

    const tabs = [
        { id: 'fullscan', page: 'pageFullScan' },
        { id: 'diettrades', page: 'pageDietTrades' },
        { id: 'metabolic', page: 'pageMetabolic' },
        { id: 'reports', page: 'pageReports' },
        { id: 'learning', page: 'pageLearning' },
        { id: 'operations', page: 'pageOperations' },
        { id: 'help', page: 'pageHelp' },
        { id: 'goals', page: 'pageGoals' },
        { id: 'medication', page: 'pageMedication' },
        { id: 'setup', page: 'pageSetup' },
        { id: 'watchfaces', page: 'pageWatchFaces' },
        { id: 'log', page: 'pageLog' },
        { id: 'export', page: 'pageExport' },
        { id: 'troubleshooting', page: 'pageTroubleshooting' }
    ];

    const results = [];
    for (const t of tabs) {
        await page.evaluate(tid => switchTab(tid), t.id);
        await new Promise(r => setTimeout(r, 200));
        const res = await page.evaluate(pid => {
            const el = document.getElementById(pid);
            if (!el) return { found: false };
            const cs = window.getComputedStyle(el);
            const rect = el.getBoundingClientRect();
            return {
                found: true,
                display: cs.display,
                visibility: cs.visibility,
                width: rect.width,
                height: rect.height,
                childCount: el.children.length,
                textLength: el.innerText.trim().length
            };
        }, t.page);
        results.push({ tab: t.id, page: t.page, ...res });
    }
    console.log(JSON.stringify(results, null, 2));
    await browser.close();
})();
"

