const puppeteer = require('puppeteer');

(async () => {
  const browser = await puppeteer.launch({
    headless: "new",
    args: ['--no-sandbox', '--disable-setuid-sandbox']
  });
  const page = await browser.newPage();

  page.on('console', msg => console.log('PAGE LOG:', msg.text()));
  page.on('pageerror', err => console.log('PAGE ERROR:', err.message));

  await page.goto('http://127.0.0.1:8899/BFM.HTM', { waitUntil: 'networkidle2' });

  // Switch to Tab 03
  await page.evaluate(() => {
    switchTab('metabolic');
  });

  await new Promise(r => setTimeout(r, 1500));

  const results = await page.evaluate(() => {
    return {
      date: document.getElementById('lblDailyIntakeDate')?.textContent,
      badge: document.getElementById('badgeDailyIntakeStatus')?.textContent,
      bCount: document.getElementById('summaryCountBreakfast')?.textContent,
      bMacro: document.getElementById('summaryMacroBreakfast')?.textContent,
      bList: document.getElementById('summaryListBreakfast')?.textContent,
      lCount: document.getElementById('summaryCountLunch')?.textContent,
      lMacro: document.getElementById('summaryMacroLunch')?.textContent,
      lList: document.getElementById('summaryListLunch')?.textContent,
      dCount: document.getElementById('summaryCountDinner')?.textContent,
      dMacro: document.getElementById('summaryMacroDinner')?.textContent,
      sCount: document.getElementById('summaryCountSnack')?.textContent,
      sMacro: document.getElementById('summaryMacroSnack')?.textContent,
      dayKcal: document.getElementById('lblDayKcal')?.textContent,
      dayNetC: document.getElementById('lblDayNetCarbs')?.textContent
    };
  });

  console.log('DOM Evaluation Results:', JSON.stringify(results, null, 2));

  await browser.close();
})();

